head.b:skin:
:root{
  --brand:#0f766e;
  --brand-dark:#115e59;
  --accent:#f59e0b;
  --text:#172033;
  --muted:#64748b;
  --bg:#f8fafc;
  --card:#ffffff;
  --border:#e2e8f0;
  --radius:18px;
  --shadow:0 12px 32px rgba(15,23,42,.08);
  --max:1180px;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;color:var(--text);background:var(--bg);font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;line-height:1.65}
a{color:inherit;text-decoration:none} img{max-width:100%;height:auto}
.container{width:min(calc(100% - 32px),var(--max));margin:auto}
.site-header{position:sticky;top:0;z-index:50;background:rgba(255,255,255,.94);backdrop-filter:blur(12px);border-bottom:1px solid rgba(226,232,240,.9)}
.nav{min-height:72px;display:flex;align-items:center;justify-content:space-between;gap:24px}
.brand{display:flex;align-items:center;gap:12px;font-weight:800;font-size:21px}
.brand-mark{width:38px;height:38px;border-radius:12px;background:linear-gradient(135deg,var(--brand),#14b8a6);display:grid;place-items:center;color:#fff;font-weight:900}
.nav-links{display:flex;align-items:center;gap:22px;font-weight:600;font-size:14px}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:46px;padding:0 20px;border-radius:12px;font-weight:700;border:1px solid transparent;transition:.2s ease}
.btn-primary{background:var(--brand);color:#fff}.btn-primary:hover{background:var(--brand-dark);transform:translateY(-1px)}
.btn-light{background:#fff;border-color:var(--border)}.btn-light:hover{border-color:#cbd5e1;transform:translateY(-1px)}
.hero{padding:88px 0 76px;background:radial-gradient(circle at 80% 20%,rgba(20,184,166,.16),transparent 30%),linear-gradient(180deg,#fff 0%,#f0fdfa 100%);border-bottom:1px solid var(--border)}
.hero-grid{display:grid;grid-template-columns:1.15fr .85fr;align-items:center;gap:54px}
.eyebrow{display:inline-flex;padding:7px 12px;border-radius:999px;background:#ccfbf1;color:#115e59;font-weight:800;font-size:13px;letter-spacing:.02em}
h1{font-size:clamp(42px,6vw,72px);line-height:1.05;margin:18px 0 20px;letter-spacing:-.045em}
.hero p{font-size:19px;color:var(--muted);max-width:680px;margin:0 0 28px}.hero-actions{display:flex;gap:12px;flex-wrap:wrap}
.hero-card{background:#fff;border:1px solid var(--border);border-radius:28px;padding:28px;box-shadow:var(--shadow)}
.hero-stat{display:grid;grid-template-columns:repeat(2,1fr);gap:14px;margin-top:16px}
.stat{padding:18px;border-radius:16px;background:#f8fafc;border:1px solid var(--border)}.stat strong{display:block;font-size:26px;color:var(--brand)}.stat span{font-size:13px;color:var(--muted)}
.section{padding:76px 0}.section-title{display:flex;justify-content:space-between;gap:24px;align-items:end;margin-bottom:28px}.section-title h2{font-size:34px;margin:0;letter-spacing:-.03em}.section-title p{margin:6px 0 0;color:var(--muted)}
.benefits{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.benefit{background:#fff;border:1px solid var(--border);border-radius:var(--radius);padding:24px}.benefit-icon{width:46px;height:46px;border-radius:14px;background:#ccfbf1;color:var(--brand-dark);display:grid;place-items:center;font-size:22px;margin-bottom:15px}.benefit h3{margin:0 0 8px;font-size:18px}.benefit p{margin:0;color:var(--muted);font-size:14px}
.jobs-toolbar{display:flex;gap:12px;justify-content:space-between;align-items:center;margin:0 0 24px;flex-wrap:wrap}.search-box{flex:1;min-width:260px;display:flex;align-items:center;background:#fff;border:1px solid var(--border);border-radius:12px;padding:0 14px}.search-box input{width:100%;border:0;outline:0;background:transparent;padding:13px 8px;font:inherit}
.jobs-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.job-card{background:#fff;border:1px solid var(--border);border-radius:var(--radius);padding:24px;display:flex;flex-direction:column;min-height:250px;transition:.2s ease}.job-card:hover{transform:translateY(-4px);box-shadow:var(--shadow);border-color:#99f6e4}.job-meta{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px}.chip{padding:5px 9px;border-radius:999px;background:#f1f5f9;color:#475569;font-size:12px;font-weight:700}.job-card h3{font-size:21px;line-height:1.35;margin:0 0 10px}.job-card p{color:var(--muted);font-size:14px;margin:0 0 20px}.job-link{margin-top:auto;color:var(--brand);font-weight:800}
.cta{background:linear-gradient(135deg,#115e59,#0f766e);color:#fff;border-radius:28px;padding:44px;display:flex;align-items:center;justify-content:space-between;gap:24px}.cta h2{margin:0 0 8px;font-size:32px}.cta p{margin:0;color:#ccfbf1}.cta .btn{background:#fff;color:#115e59}
.site-footer{margin-top:72px;background:#0f172a;color:#cbd5e1;padding:52px 0 28px}.footer-grid{display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:30px}.site-footer h4{color:#fff;margin-top:0}.site-footer a{color:#cbd5e1}.copyright{margin-top:36px;padding-top:20px;border-top:1px solid #334155;font-size:13px;color:#94a3b8}
.post-wrap{width:min(calc(100% - 32px),860px);margin:50px auto;background:#fff;padding:38px;border:1px solid var(--border);border-radius:24px}.post-title{font-size:38px;line-height:1.15;margin:0 0 10px}.post-body{font-size:16px}.post-body h2,.post-body h3{margin-top:30px}.post-body ul{padding-left:22px}.apply-box{margin-top:34px;padding:24px;border-radius:18px;background:#f0fdfa;border:1px solid #99f6e4}.mobile-toggle{display:none}
@media (max-width:900px){.hero-grid,.footer-grid{grid-template-columns:1fr}.benefits{grid-template-columns:repeat(2,1fr)}.jobs-grid{grid-template-columns:repeat(2,1fr)}.nav-links{display:none}.mobile-toggle{display:inline-flex}}
@media (max-width:620px){.hero{padding:58px 0}.section{padding:56px 0}.benefits,.jobs-grid{grid-template-columns:1fr}.cta{padding:28px;align-items:flex-start;flex-direction:column}.post-wrap{padding:24px}h1{font-size:44px}}
